@Composable
fun PlayerSurface(
    channel: Channel?,
    channels: List<Channel> = emptyList(),
    selectedIndex: Int = 0,
    muted: Boolean = false,
    captionsEnabled: Boolean = false,
    preferredAudioLanguage: String? = "pt-BR",
    maxVideoHeight: Int = 0,
    onTelemetry: (PlaybackTelemetry) -> Unit = {}
) {
    when (channel?.source) {
        ChannelSource.HLS,
        ChannelSource.IPTV -> StreamSurface(
            channel = channel,
            channels = channels,
            selectedIndex = selectedIndex,
            muted = muted,
            captionsEnabled = captionsEnabled,
            preferredAudioLanguage = preferredAudioLanguage,
            maxVideoHeight = maxVideoHeight,
            onTelemetry = onTelemetry
        )
        else -> {
            LaunchedEffect(channel?.id) {
                onTelemetry(PlaybackTelemetry(status = "Sem stream reproduzível"))
            }
            IdleSurface()
        }
    }
}

@OptIn(UnstableApi::class)
@Composable
private fun StreamSurface(
    channel: Channel,
    channels: List<Channel>,
    selectedIndex: Int,
    muted: Boolean,
    captionsEnabled: Boolean,
    preferredAudioLanguage: String?,
    maxVideoHeight: Int,
    onTelemetry: (PlaybackTelemetry) -> Unit
) {
    val context = LocalContext.current
    val scope = rememberCoroutineScope()
    val healthStore = remember { StreamHealthStore(context.applicationContext) }
    val engine = remember { TurboPreloadEngine(context.applicationContext) }

    val candidates = remember(channel.id, channel.uri, channel.backupUris) {
        healthStore.order(
            PlaybackRecoveryPolicy.sanitize(channel.playbackUris())
        )
    }

    var candidateIndex by remember(channel.id, candidates) { mutableIntStateOf(0) }
    var retryAttempt by remember(channel.id) { mutableIntStateOf(0) }
    var retryToken by remember(channel.id) { mutableIntStateOf(0) }
    var firstFrameMs by remember(channel.id) { mutableLongStateOf(0L) }
    var bufferCount by remember(channel.id) { mutableIntStateOf(0) }
    var prepareStartedAt by remember(channel.id) { mutableLongStateOf(0L) }
    var hasReadyOnce by remember(channel.id) { mutableStateOf(false) }

    if (candidates.isEmpty()) {
        LaunchedEffect(channel.id) {
            onTelemetry(PlaybackTelemetry(status = "Canal sem URL válida"))
        }
        IdleSurface()
        return
    }

    val player = engine.player

    LaunchedEffect(channels, selectedIndex) {
        engine.sync(
            channels = channels,
            currentIndex = selectedIndex,
            healthStore = healthStore
        )
    }

    LaunchedEffect(muted) {
        player.volume = if (muted) 0f else 1f
    }

    LaunchedEffect(captionsEnabled, preferredAudioLanguage, maxVideoHeight) {
        val builder = player.trackSelectionParameters
            .buildUpon()
            .setPreferredTextLanguages("pt-BR", "pt")
            .setTrackTypeDisabled(C.TRACK_TYPE_TEXT, !captionsEnabled)

        if (preferredAudioLanguage.isNullOrBlank()) {
            builder.setPreferredAudioLanguages()
        } else {
            builder.setPreferredAudioLanguages(preferredAudioLanguage, "pt")
        }

        if (maxVideoHeight > 0) {
            builder.setMaxVideoSize(Int.MAX_VALUE, maxVideoHeight)
        } else {
            builder.clearVideoSizeConstraints()
        }

        player.trackSelectionParameters = builder.build()
    }

    val index = candidateIndex.coerceIn(0, candidates.lastIndex)
    val uri = candidates[index]

    fun telemetry(status: String, videoSize: VideoSize = player.videoSize) {
        val format = player.videoFormat
        val resolution = if (videoSize.width > 0 && videoSize.height > 0) {
            "\${videoSize.width}×\${videoSize.height}"
        } else {
            "—"
        }
        onTelemetry(
            PlaybackTelemetry(
                status = status,
                resolution = resolution,
                streamIndex = index + 1,
                streamCount = candidates.size,
                score = healthStore.score(uri),
                firstFrameMs = firstFrameMs,
                bufferCount = bufferCount,
                bitrateKbps = ((format?.bitrate ?: 0) / 1000).coerceAtLeast(0),
                frameRate = format?.frameRate?.takeIf { it > 0f } ?: 0f,
                videoCodec = format?.codecs
                    ?: format?.sampleMimeType
                    ?: "—"
            )
        )
    }

    DisposableEffect(player, uri, candidates.size, retryToken) {
        var bufferingWatch: Job? = null
        var recovering = false

        fun recoverPlayback(reason: String) {
            if (recovering) return
            recovering = true
            healthStore.recordFailure(uri)
            telemetry("$reason • procurando alternativa")

            val next = PlaybackRecoveryPolicy.nextCandidate(candidateIndex, candidates.size)
            if (next != null) {
                candidateIndex = next
                retryAttempt = 0
                return
            }

            val currentAttempt = retryAttempt
            scope.launch {
                telemetry("Todas as alternativas falharam • nova tentativa")
                delay(PlaybackRecoveryPolicy.retryDelay(currentAttempt))
                retryAttempt = (currentAttempt + 1).coerceAtMost(5)
                candidateIndex = 0
                retryToken += 1
            }
        }

        val listener = object : Player.Listener {
            override fun onPlayerError(error: PlaybackException) {
                bufferingWatch?.cancel()
                recoverPlayback("Falha")
            }

            override fun onPlaybackStateChanged(playbackState: Int) {
                when (playbackState) {
                    Player.STATE_READY -> {
                        bufferingWatch?.cancel()
                        bufferingWatch = null
                        recovering = false
                        retryAttempt = 0
                        hasReadyOnce = true
                        telemetry("Reproduzindo")
                    }

                    Player.STATE_BUFFERING -> {
                        if (hasReadyOnce) bufferCount += 1
                        telemetry(if (hasReadyOnce) "Rebuffering" else "Carregando")
                        bufferingWatch?.cancel()
                        bufferingWatch = scope.launch {
                            delay(BUFFERING_RECOVERY_MS)
                            if (player.playbackState == Player.STATE_BUFFERING) {
                                recoverPlayback("Buffer excedido")
                            }
                        }
                    }

                    Player.STATE_ENDED -> telemetry("Transmissão encerrada")
                    else -> Unit
                }
            }

            override fun onRenderedFirstFrame() {
                if (firstFrameMs <= 0L && prepareStartedAt > 0L) {
                    firstFrameMs = (SystemClock.elapsedRealtime() - prepareStartedAt)
                        .coerceAtLeast(1L)
                    healthStore.recordReady(uri, firstFrameMs)
                    telemetry("Reproduzindo")
                }
            }

            override fun onVideoSizeChanged(videoSize: VideoSize) {
                if (player.playbackState == Player.STATE_READY) {
                    telemetry("Reproduzindo", videoSize)
                }
            }

            override fun onTracksChanged(tracks: androidx.media3.common.Tracks) {
                telemetry(
                    if (player.playbackState == Player.STATE_READY) "Reproduzindo" else "Preparando faixas"
                )
            }
        }

        player.addListener(listener)
        telemetry("Conectando")

        onDispose {
            bufferingWatch?.cancel()
            player.removeListener(listener)
        }
    }

    LaunchedEffect(channel.id, uri, retryToken) {
        val mediaItem = mediaItem(channel.id, uri)
        prepareStartedAt = SystemClock.elapsedRealtime()
        firstFrameMs = 0L
        hasReadyOnce = false

        player.stop()
        player.clearMediaItems()

        val preloaded: MediaSource? = if (candidateIndex == 0) {
            engine.mediaSourceFor(mediaItem)
        } else {
            null
        }

        if (preloaded != null) {
            player.setMediaSource(preloaded)
        } else {
            player.setMediaItem(mediaItem)
        }

        player.prepare()
        player.play()
        engine.setCurrentIndex(selectedIndex)
    }

    DisposableEffect(context, player) {
        val connectivity = context.getSystemService(ConnectivityManager::class.java)
        val callback = object : ConnectivityManager.NetworkCallback() {
            override fun onAvailable(network: Network) {
                scope.launch {
                    if (player.playbackState != Player.STATE_READY) {
                        delay(350)
                        retryAttempt = 0
                        candidateIndex = 0
                        retryToken += 1
                    }
                }
            }
        }

        runCatching { connectivity.registerDefaultNetworkCallback(callback) }

        onDispose {
            runCatching { connectivity.unregisterNetworkCallback(callback) }
        }
    }

    DisposableEffect(engine) {
        onDispose { engine.release() }
    }

    AndroidView(
        factory = {
            PlayerView(it).apply {
                useController = false
                resizeMode = AspectRatioFrameLayout.RESIZE_MODE_FIT
                setShowBuffering(PlayerView.SHOW_BUFFERING_WHEN_PLAYING)
                this.player = player
                isFocusable = true
            }
        },
        update = { it.player = player },
        modifier = Modifier
            .fillMaxSize()
            .background(Color.Black)
            .focusable()
    )
}

@OptIn(UnstableApi::class)
private class TurboPreloadEngine(
    context: android.content.Context
) {
    private class StatusControl : TargetPreloadStatusControl<Int, DefaultPreloadManager.PreloadStatus> {
        var currentIndex: Int = 0

        override fun getTargetPreloadStatus(
            rankingData: Int
        ): DefaultPreloadManager.PreloadStatus {
            val distance = abs(rankingData - currentIndex)
            return when (distance) {
                1 -> DefaultPreloadManager.PreloadStatus.specifiedRangeLoaded(PRELOAD_MS)
                2 -> DefaultPreloadManager.PreloadStatus.PRELOAD_STATUS_TRACKS_SELECTED
                else -> DefaultPreloadManager.PreloadStatus.PRELOAD_STATUS_NOT_PRELOADED
            }
        }
    }

    private val statusControl = StatusControl()
    private val loadControl = DefaultLoadControl.Builder()
        .setBufferDurationsMs(
            1_500,
            15_000,
            500,
            1_000
        )
        .build()
    private val renderersFactory = DefaultRenderersFactory(context)
        .setEnableDecoderFallback(true)
    private val builder = DefaultPreloadManager.Builder(context, statusControl)
        .setLoadControl(loadControl)
        .setRenderersFactory(renderersFactory)

    private val preloadManager: DefaultPreloadManager = builder.build()
    val player: ExoPlayer = builder.buildExoPlayer()
    private val managed = linkedMapOf<String, MediaItem>()

    init {
        player.playWhenReady = true
        player.setHandleAudioBecomingNoisy(true)
        player.trackSelectionParameters = player.trackSelectionParameters
            .buildUpon()
            .setPreferredAudioLanguages("pt-BR", "pt")
            .setPreferredTextLanguages("pt-BR", "pt")
            .setTrackTypeDisabled(C.TRACK_TYPE_TEXT, true)
            .build()
    }

    fun sync(
        channels: List<Channel>,
        currentIndex: Int,
        healthStore: StreamHealthStore
    ) {
        if (channels.isEmpty()) return
        statusControl.currentIndex = currentIndex
        val size = channels.size
        val wantedIndices = listOf(
            currentIndex,
            (currentIndex - 1).floorMod(size),
            (currentIndex + 1).floorMod(size),
            (currentIndex + 2).floorMod(size)
        ).distinct()

        val wanted = linkedMapOf<String, Pair<MediaItem, Int>>()
        wantedIndices.forEach { index ->
            val channel = channels.getOrNull(index) ?: return@forEach
            val uri = healthStore.order(
                PlaybackRecoveryPolicy.sanitize(channel.playbackUris())
            ).firstOrNull() ?: return@forEach
            wanted[channel.id] = mediaItem(channel.id, uri) to index
        }

        managed.keys.toList().forEach { channelId ->
            val old = managed[channelId]
            val next = wanted[channelId]?.first
            if (old != null && (next == null || old != next)) {
                preloadManager.remove(old)
                managed.remove(channelId)
            }
        }

        wanted.forEach { (channelId, pair) ->
            val (item, ranking) = pair
            if (managed[channelId] == null) {
                preloadManager.add(item, ranking)
                managed[channelId] = item
            }
        }

        preloadManager.setCurrentPlayingIndex(currentIndex)
        preloadManager.invalidate()
    }

    fun setCurrentIndex(index: Int) {
        statusControl.currentIndex = index
        preloadManager.setCurrentPlayingIndex(index)
        preloadManager.invalidate()
    }

    fun mediaSourceFor(item: MediaItem): MediaSource? =
        preloadManager.getMediaSource(item)

    fun release() {
        preloadManager.release()
        player.release()
    }

    private fun Int.floorMod(size: Int): Int {
        val value = this % size
        return if (value < 0) value + size else value
    }

    companion object {
        private const val PRELOAD_MS = 2_000L
    }
}

private fun mediaItem(channelId: String, uri: String): MediaItem {
    val lower = uri.lowercase()
    return MediaItem.Builder()
        .setMediaId(channelId + "|" + uri.hashCode())
        .setUri(uri)
        .apply {
            when {
                ".m3u8" in lower -> setMimeType(MimeTypes.APPLICATION_M3U8)
                ".mpd" in lower -> setMimeType(MimeTypes.APPLICATION_MPD)
            }
        }
        .build()
}

@Composable
private fun IdleSurface() {
    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(
                Brush.radialGradient(
                    colors = listOf(Color(0xFF12212C), SanchesColors.Background),
                    radius = 1500f
                )
            )
    )
}

