                AppScreen.LIVE -> ChannelNavigatorScreen(state, controller)
                AppScreen.MOVIES -> CuratedScreen(
                    title = "Filmes & Cinema",
                    subtitle = "Canais identificados como filmes e cinema",
                    channels = state.channels.filter(::isMovieChannel),
                    programs = state.programs,
                    favorites = state.favorites,
