                AppScreen.SEARCH -> SearchScreen(state, controller::select)
                AppScreen.SOURCES -> SourcesScreen(state, controller)
                AppScreen.DIAGNOSTICS -> DiagnosticsScreen(state, controller.startInLastChannel)
                AppScreen.WATCH -> Unit
