@Composable
private fun HomeScreen(
    state: AppUiState,
    controller: ZappController
) {
    val hero = state.currentChannel ?: state.channels.firstOrNull()
    val program = hero?.let { state.programs[it.id] }
    val rankedNow = remember(
        state.channels,
        state.favorites,
        state.recentChannelIds,
        state.mostWatchedIds,
        state.programs
    ) {
        HomeChannelRanker.rank(
            channels = state.channels,
            favorites = state.favorites,
            recentIds = state.recentChannelIds,
            mostWatchedIds = state.mostWatchedIds,
            programs = state.programs
        ).take(14)
    }

    LazyColumn(
        modifier = Modifier
            .fillMaxSize()
            .padding(horizontal = 34.dp, vertical = 28.dp),
        verticalArrangement = Arrangement.spacedBy(20.dp)
    ) {
        item {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        "SANCHESTV",
                        color = SanchesColors.PrimaryText,
                        fontSize = 32.sp,
                        fontWeight = FontWeight.Black,
                        letterSpacing = 2.sp
                    )
                    Text(
                        state.onlineStatus,
                        color = SanchesColors.SecondaryText,
                        fontSize = 14.sp
                    )
                }

                Text(
                    SimpleDateFormat("HH:mm", Locale("pt", "BR")).format(Date()),
                    color = SanchesColors.SecondaryText,
                    fontSize = 18.sp
                )
            }
        }

        item {
            HeroCard(
                channel = hero,
                program = program,
                onWatch = {
                    if (hero != null) controller.select(hero)
                    else controller.open(AppScreen.LIVE)
                }
            )
        }

        item {
            SectionTitle(
                title = "Agora na TV",
                subtitle = "\${state.channels.size} canais agregados"
            )
            Spacer(Modifier.height(12.dp))
            ChannelRail(
                channels = state.channels.take(14),
                programs = state.programs,
                favorites = state.favorites,
                onSelect = controller::select,
                onFavorite = controller::toggleFavorite
            )
        }

        item {
            val recent = state.recentChannelIds
                .mapNotNull { id -> state.channels.firstOrNull { it.id == id } }
                .take(12)
            if (recent.isNotEmpty()) {
                SectionTitle("Continuar assistindo", "Canais vistos recentemente")
                Spacer(Modifier.height(12.dp))
                ChannelRail(
                    channels = recent,
                    programs = state.programs,
                    favorites = state.favorites,
                    onSelect = controller::select,
                    onFavorite = controller::toggleFavorite
                )
            }
        }

        item {
            val mostWatched = state.mostWatchedIds
                .mapNotNull { id -> state.channels.firstOrNull { it.id == id } }
                .take(12)
            if (mostWatched.isNotEmpty()) {
                SectionTitle("Mais assistidos", "Baseado no seu uso neste dispositivo")
                Spacer(Modifier.height(12.dp))
                ChannelRail(
                    channels = mostWatched,
                    programs = state.programs,
                    favorites = state.favorites,
                    onSelect = controller::select,
                    onFavorite = controller::toggleFavorite
                )
            }
        }

        item {
            val now = System.currentTimeMillis()
            val upcomingIds = state.schedule.entries
                .mapNotNull { (channelId, slots) ->
                    slots.firstOrNull { slot ->
                        slot.startMillis in (now + 1)..(now + 45L * 60L * 1000L)
                    }?.let { channelId to it.startMillis }
                }
                .sortedBy { it.second }
                .map { it.first }
                .distinct()
                .take(12)
            val upcomingChannels = upcomingIds.mapNotNull { id ->
                state.channels.firstOrNull { it.id == id }
            }

            if (upcomingChannels.isNotEmpty()) {
                SectionTitle("Começando em breve", "Programação prevista nos próximos 45 minutos")
                Spacer(Modifier.height(12.dp))
                ChannelRail(
                    channels = upcomingChannels,
                    programs = state.programs,
                    favorites = state.favorites,
                    onSelect = controller::select,
                    onFavorite = controller::toggleFavorite
                )
            }
        }

        item {
            val favorites = state.channels.filter { it.id in state.favorites }.take(12)
            if (favorites.isNotEmpty()) {
                SectionTitle("Minha TV", "Favoritos")
                Spacer(Modifier.height(12.dp))
                ChannelRail(
                    channels = favorites,
                    programs = state.programs,
                    favorites = state.favorites,
                    onSelect = controller::select,
                    onFavorite = controller::toggleFavorite
                )
            }
        }
    }
}

