package com.mukasanches.zapptv.vod

import android.content.Context
import org.json.JSONObject
import java.net.HttpURLConnection
import java.net.URLEncoder
import java.net.URL

/**
 * Optional metadata adapters. Credentials are intentionally supplied at runtime/build config;
 * no secret is committed to the APK repository.
 */
class MetadataRepository(private val context: Context) {
    fun tmdbSearch(query: String, bearerToken: String): List<VodItem> {
        if (query.isBlank() || bearerToken.isBlank()) return emptyList()
        val encoded = URLEncoder.encode(query, "UTF-8")
        val json = getJson(
            "https://api.themoviedb.org/3/search/multi?query=$encoded&language=pt-BR&include_adult=false",
            mapOf("Authorization" to "Bearer $bearerToken")
        ) ?: return emptyList()
        val results = json.optJSONArray("results") ?: return emptyList()
        return buildList {
            for (i in 0 until minOf(results.length(), 40)) {
                val item = results.optJSONObject(i) ?: continue
                val mediaType = item.optString("media_type")
                if (mediaType != "movie" && mediaType != "tv") continue
                val title = item.optString(if (mediaType == "movie") "title" else "name")
                if (title.isBlank()) continue
                add(
                    VodItem(
                        id = "tmdb:" + mediaType + ":" + item.optInt("id"),
                        title = title,
                        overview = item.optString("overview"),
                        posterUrl = item.optString("poster_path").takeIf { it.isNotBlank() }
                            ?.let { "https://image.tmdb.org/t/p/w500$it" },
                        backdropUrl = item.optString("backdrop_path").takeIf { it.isNotBlank() }
                            ?.let { "https://image.tmdb.org/t/p/w1280$it" },
                        year = item.optString(if (mediaType == "movie") "release_date" else "first_air_date")
                            .take(4).takeIf { it.length == 4 },
                        source = "TMDB",
                        kind = if (mediaType == "movie") VodItem.Kind.MOVIE else VodItem.Kind.SERIES
                    )
                )
            }
        }
    }

    fun openSubtitlesSearch(imdbId: String, apiKey: String): List<String> {
        if (imdbId.isBlank() || apiKey.isBlank()) return emptyList()
        val numeric = imdbId.removePrefix("tt")
        val json = getJson(
            "https://api.opensubtitles.com/api/v1/subtitles?imdb_id=$numeric&languages=pt-br",
            mapOf(
                "Api-Key" to apiKey,
                "User-Agent" to "SANCHESTV v2.2"
            )
        ) ?: return emptyList()
        val data = json.optJSONArray("data") ?: return emptyList()
        return buildList {
            for (i in 0 until minOf(data.length(), 20)) {
                val attributes = data.optJSONObject(i)?.optJSONObject("attributes") ?: continue
                val files = attributes.optJSONArray("files") ?: continue
                for (j in 0 until files.length()) {
                    files.optJSONObject(j)?.optString("file_name")
                        ?.takeIf { it.isNotBlank() }
                        ?.let(::add)
                }
            }
        }
    }

    private fun getJson(url: String, headers: Map<String, String>): JSONObject? {
        var connection: HttpURLConnection? = null
        return runCatching {
            connection = (URL(url).openConnection() as HttpURLConnection).apply {
                connectTimeout = 6000
                readTimeout = 10000
                requestMethod = "GET"
                setRequestProperty("Accept", "application/json")
                setRequestProperty("User-Agent", "SANCHESTV/2.2 AndroidTV")
                headers.forEach { (key, value) -> setRequestProperty(key, value) }
            }
            if (connection!!.responseCode !in 200..299) return@runCatching null
            connection!!.inputStream.bufferedReader().use { JSONObject(it.readText()) }
        }.getOrNull().also { connection?.disconnect() }
    }
}

