package com.mukasanches.zapptv.data

import android.content.Context
import org.json.JSONArray
import java.net.URI
import java.security.MessageDigest

class UserM3uSourceStore(context: Context) {
    private val prefs = context.getSharedPreferences("sanchestv-user-sources", Context.MODE_PRIVATE)

    fun sources(): List<IptvSource> {
        val raw = prefs.getString(KEY_SOURCES, null) ?: return emptyList()
        return runCatching {
            val array = JSONArray(raw)
            buildList {
                for (index in 0 until array.length()) {
                    val url = array.optString(index).trim()
                    toSource(url)?.let(::add)
                }
            }.distinctBy { it.id }
        }.getOrDefault(emptyList())
    }

    fun add(url: String): IptvSource? {
        val source = toSource(url) ?: return null
        val updated = (sources().map(IptvSource::url) + source.url)
            .distinct()
            .take(MAX_USER_SOURCES)

        val array = JSONArray()
        updated.forEach(array::put)
        prefs.edit().putString(KEY_SOURCES, array.toString()).apply()
        return source
    }

    fun remove(id: String) {
        val updated = sources().filterNot { it.id == id }.map(IptvSource::url)
        val array = JSONArray()
        updated.forEach(array::put)
        prefs.edit().putString(KEY_SOURCES, array.toString()).apply()
    }

    private fun toSource(rawUrl: String): IptvSource? {
        val url = rawUrl.trim()
        if (!url.startsWith("https://", ignoreCase = true)) return null

        val uri = runCatching { URI(url) }.getOrNull() ?: return null
        val host = uri.host?.takeIf(String::isNotBlank) ?: return null
        val id = "user-" + shortHash(url)

        return IptvSource(
            id = id,
            name = "Minha fonte • $host",
            url = url,
            priority = 130,
            market = "Adicionada pelo usuário",
            enabled = true
        )
    }

    private fun shortHash(value: String): String {
        val digest = MessageDigest.getInstance("SHA-256").digest(value.toByteArray())
        return digest.take(8).joinToString("") { "%02x".format(it) }
    }

    companion object {
        private const val KEY_SOURCES = "https_m3u_sources"
        private const val MAX_USER_SOURCES = 24
    }
}

package com.mukasanches.zapptv.data

import android.content.Context
import org.json.JSONObject

data class SourceHealth(
    val sourceId: String,
    val lastAttemptMillis: Long = 0L,
    val lastSuccessMillis: Long = 0L,
    val successCount: Int = 0,
    val failureCount: Int = 0,
    val channelCount: Int = 0
) {
    val isHealthy: Boolean
        get() = lastSuccessMillis > 0L && (
            lastAttemptMillis == 0L || lastSuccessMillis >= lastAttemptMillis
        )

    fun reliabilityScore(): Int {
        val total = successCount + failureCount
        if (total <= 0) return 0
        return ((successCount.toFloat() / total.toFloat()) * 100f).toInt()
    }
}

class SourceHealthStore(context: Context) {
    private val prefs = context.getSharedPreferences("sanchestv-source-health", Context.MODE_PRIVATE)

    fun get(sourceId: String): SourceHealth {
        val raw = prefs.getString(sourceId, null) ?: return SourceHealth(sourceId)
        return runCatching {
            val json = JSONObject(raw)
            SourceHealth(
                sourceId = sourceId,
                lastAttemptMillis = json.optLong("lastAttemptMillis", 0L),
                lastSuccessMillis = json.optLong("lastSuccessMillis", 0L),
                successCount = json.optInt("successCount", 0),
                failureCount = json.optInt("failureCount", 0),
                channelCount = json.optInt("channelCount", 0)
            )
        }.getOrDefault(SourceHealth(sourceId))
    }

    fun recordSuccess(sourceId: String, channelCount: Int) {
        val old = get(sourceId)
        save(
            old.copy(
                lastAttemptMillis = System.currentTimeMillis(),
                lastSuccessMillis = System.currentTimeMillis(),
                successCount = (old.successCount + 1).coerceAtMost(MAX_COUNT),
                channelCount = channelCount.coerceAtLeast(0)
            )
        )
    }

    fun recordFailure(sourceId: String) {
        val old = get(sourceId)
        save(
            old.copy(
                lastAttemptMillis = System.currentTimeMillis(),
                failureCount = (old.failureCount + 1).coerceAtMost(MAX_COUNT)
            )
        )
    }

    fun snapshot(sourceIds: List<String>): Map<String, SourceHealth> =
        sourceIds.associateWith(::get)

    private fun save(health: SourceHealth) {
        val json = JSONObject()
            .put("lastAttemptMillis", health.lastAttemptMillis)
            .put("lastSuccessMillis", health.lastSuccessMillis)
            .put("successCount", health.successCount)
            .put("failureCount", health.failureCount)
            .put("channelCount", health.channelCount)

        prefs.edit().putString(health.sourceId, json.toString()).apply()
    }

    companion object {
        private const val MAX_COUNT = 1_000_000
    }
}

package com.mukasanches.zapptv.playback

import android.content.Context
import org.json.JSONObject

data class StreamHealth(
    val successCount: Int = 0,
    val failureCount: Int = 0,
    val averageFirstFrameMs: Long = 0L,
    val lastFailureMillis: Long = 0L
) {
    val total: Int get() = successCount + failureCount

    fun reliability(): Int =
        if (total == 0) 50
        else ((successCount.toFloat() / total.toFloat()) * 100f).toInt()

    fun quarantined(now: Long = System.currentTimeMillis()): Boolean =
        failureCount >= 3 &&
            failureCount > successCount &&
            now - lastFailureMillis < QUARANTINE_MS

    companion object {
        private const val QUARANTINE_MS = 2L * 60L * 60L * 1000L
    }
}

class StreamHealthStore(context: Context) {
    private val prefs = context.getSharedPreferences("sanchestv-stream-health", Context.MODE_PRIVATE)

    fun order(urls: List<String>): List<String> =
        urls.distinct().sortedWith(
            compareBy<String> { health(it).quarantined() }
                .thenByDescending(::score)
                .thenBy { health(it).averageFirstFrameMs.takeIf { value -> value > 0L } ?: Long.MAX_VALUE }
        )

    fun recordReady(url: String, firstFrameMs: Long = 0L) {
        val old = health(url)
        val success = (old.successCount + 1).coerceAtMost(MAX_COUNT)
        val average = when {
            firstFrameMs <= 0L -> old.averageFirstFrameMs
            old.averageFirstFrameMs <= 0L -> firstFrameMs
            else -> ((old.averageFirstFrameMs * old.successCount) + firstFrameMs) / success
        }
        save(
            url,
            old.copy(
                successCount = success,
                averageFirstFrameMs = average.coerceAtMost(MAX_FIRST_FRAME_MS)
            )
        )
    }

    fun recordFailure(url: String) {
        val old = health(url)
        save(
            url,
            old.copy(
                failureCount = (old.failureCount + 1).coerceAtMost(MAX_COUNT),
                lastFailureMillis = System.currentTimeMillis()
            )
        )
    }

    fun score(url: String): Int {
        val value = health(url)
        var score = value.reliability()
        if (value.averageFirstFrameMs in 1..1200) score += 10
        if (value.averageFirstFrameMs > 5000) score -= 12
        if (value.quarantined()) score -= 45
        return score.coerceIn(0, 100)
    }

    fun health(url: String): StreamHealth {
        val raw = prefs.getString(key(url), null) ?: return StreamHealth()
        val json = runCatching { JSONObject(raw) }.getOrNull() ?: return StreamHealth()
        return StreamHealth(
            successCount = json.optInt("ok", 0),
            failureCount = json.optInt("fail", 0),
            averageFirstFrameMs = json.optLong("avgFirstFrameMs", 0L),
            lastFailureMillis = json.optLong("lastFailureMillis", 0L)
        )
    }

    private fun save(url: String, health: StreamHealth) {
        prefs.edit().putString(
            key(url),
            JSONObject()
                .put("ok", health.successCount)
                .put("fail", health.failureCount)
                .put("avgFirstFrameMs", health.averageFirstFrameMs)
                .put("lastFailureMillis", health.lastFailureMillis)
                .toString()
        ).apply()
    }

    private fun key(url: String): String = "u_" + url.hashCode().toUInt().toString(16)

    companion object {
        private const val MAX_COUNT = 1_000_000
        private const val MAX_FIRST_FRAME_MS = 60_000L
    }
}

package com.mukasanches.zapptv.data

import android.content.Context
import com.mukasanches.zapptv.model.Channel
import com.mukasanches.zapptv.model.ProgramInfo
import com.mukasanches.zapptv.model.ProgramSlot
import java.io.BufferedInputStream
import java.io.BufferedReader
import java.io.File
import java.io.FileInputStream
import java.io.FileOutputStream
import java.io.InputStream
import java.io.InputStreamReader
import java.net.HttpURLConnection
import java.net.URL
import java.util.zip.GZIPInputStream

data class IptvSnapshot(
    val channels: List<Channel> = emptyList(),
    val programs: Map<String, ProgramInfo> = emptyMap(),
    val schedule: Map<String, List<ProgramSlot>> = emptyMap(),
    val epgUrls: List<String> = emptyList(),
    val lastUpdatedMillis: Long = 0L,
    val sourceCount: Int = 0,
    val healthySourceCount: Int = 0,
    val userSourceCount: Int = 0,
    val sourceHealth: Map<String, SourceHealth> = emptyMap(),
    val status: String = "Inicializando central IPTV"
)

class IptvRepository(context: Context) {
    private val appContext = context.applicationContext
    private val directory = File(appContext.filesDir, "sanchestv-cache").apply { mkdirs() }
    private val legacyDirectory = File(appContext.filesDir, "zapptv-cache")
    private val userSources = UserM3uSourceStore(appContext)
    private val healthStore = SourceHealthStore(appContext)

    init {
        migrateLegacyCache()
    }

    fun configuredSources(): List<IptvSource> = allSources()

    fun addUserSource(url: String): IptvSource? = userSources.add(url)

    fun removeUserSource(id: String) {
        val source = userSources.sources().firstOrNull { it.id == id }
        if (source != null) {
            playlistFile(source).delete()
            userSources.remove(id)
        }
    }

    fun loadCached(): IptvSnapshot {
        val sources = allSources().filter(IptvSource::enabled)
        val catalogs = cachedCatalogs(sources)
        val channels = mergeChannels(catalogs)
        val epg = readEpg(channels)
        val programs = epg.currentPrograms
        val updated = allCacheFiles(sources).filter(File::isFile).maxOfOrNull(File::lastModified) ?: 0L

        return snapshot(
            sources = sources,
            catalogs = catalogs,
            channels = channels,
            programs = programs,
            schedule = epg.timeline,
            updated = updated,
            cached = true
        )
    }

    fun refresh(force: Boolean = false): IptvSnapshot {
        val sources = allSources().filter(IptvSource::enabled)

        sources.forEach { source ->
            val file = playlistFile(source)
            val shouldRefresh = force || isStale(file, PLAYLIST_TTL_MS)
            if (shouldRefresh) {
                val downloaded = download(
                    url = source.url,
                    target = file,
                    maxBytes = MAX_PLAYLIST_BYTES,
                    validator = ::isValidPlaylist
                )

                if (!downloaded) {
                    healthStore.recordFailure(source.id)
                }
            }

            val parsed = if (file.isFile && file.length() > 0L) parsePlaylist(source, file) else null
            if (parsed != null && parsed.channels.isNotEmpty()) {
                healthStore.recordSuccess(source.id, parsed.channels.size)
            } else if (!shouldRefresh) {
                healthStore.recordFailure(source.id)
            }
        }

        val catalogs = cachedCatalogs(sources)
        val channels = mergeChannels(catalogs)

        IptvSourceRegistry.epg
            .sortedByDescending(EpgSource::priority)
            .forEach { source ->
                val file = epgFile(source)
                if (force || isStale(file, EPG_TTL_MS)) {
                    download(
                        url = source.url,
                        target = file,
                        maxBytes = MAX_EPG_BYTES,
                        validator = ::isValidEpg
                    )
                }
            }

        val epg = readEpg(channels)
        val programs = epg.currentPrograms
        val updated = allCacheFiles(sources).filter(File::isFile).maxOfOrNull(File::lastModified) ?: 0L

        return snapshot(
            sources = sources,
            catalogs = catalogs,
            channels = channels,
            programs = programs,
            schedule = epg.timeline,
            updated = updated,
            cached = false
        )
    }

    private fun snapshot(
        sources: List<IptvSource>,
        catalogs: List<Pair<IptvSource, ParsedIptvPlaylist>>,
        channels: List<Channel>,
        programs: Map<String, ProgramInfo>,
        schedule: Map<String, List<ProgramSlot>>,
        updated: Long,
        cached: Boolean
    ): IptvSnapshot {
        val userCount = sources.count { it.id.startsWith("user-") }
        val health = healthStore.snapshot(sources.map(IptvSource::id))
        val healthyCount = catalogs.size

        val status = when {
            channels.isEmpty() && cached -> "Sem cache IPTV; catálogo essencial ativo"
            channels.isEmpty() -> "Fontes indisponíveis; catálogo essencial ativo"
            healthyCount < sources.size ->
                "${channels.size} canais • ${healthyCount}/${sources.size} fontes válidas"
            programs.isEmpty() ->
                "${channels.size} canais • ${sources.size} fontes • EPG atualizando"
            else ->
                "${channels.size} canais • ${sources.size} fontes • EPG Agora/Depois"
        }

        return IptvSnapshot(
            channels = channels,
            programs = programs,
            schedule = schedule,
            epgUrls = IptvSourceRegistry.epg.map(EpgSource::url),
            lastUpdatedMillis = updated,
            sourceCount = sources.size,
            healthySourceCount = healthyCount,
            userSourceCount = userCount,
            sourceHealth = health,
            status = status
        )
    }

    private fun allSources(): List<IptvSource> =
        (IptvSourceRegistry.builtIn + userSources.sources())
            .distinctBy(IptvSource::id)

    private fun cachedCatalogs(
        sources: List<IptvSource>
    ): List<Pair<IptvSource, ParsedIptvPlaylist>> =
        sources.mapNotNull { source ->
            val file = playlistFile(source)
            if (!file.isFile || file.length() <= 0L) return@mapNotNull null

            val parsed = parsePlaylist(source, file)
            if (parsed.channels.isEmpty()) null else source to parsed
        }

    private fun parsePlaylist(source: IptvSource, file: File): ParsedIptvPlaylist =
        runCatching {
            BufferedReader(InputStreamReader(FileInputStream(file), Charsets.UTF_8)).use { reader ->
                val parsed = IptvPlaylistParser.parse(reader)
                val filtered = source.groupFilter?.let { wanted ->
                    parsed.channels.filter { it.category.equals(wanted, ignoreCase = true) }
                } ?: parsed.channels

                parsed.copy(
                    channels = filtered.map { channel ->
                        channel.copy(
                            sourceName = source.name,
                            sourceNames = listOf(source.name)
                        )
                    }
                )
            }
        }.getOrDefault(ParsedIptvPlaylist(emptyList(), emptyList()))

    private fun mergeChannels(
        catalogs: List<Pair<IptvSource, ParsedIptvPlaylist>>
    ): List<Channel> {
        val merged = linkedMapOf<String, Channel>()
        val aliasToPrimary = mutableMapOf<String, String>()

        catalogs
            .sortedByDescending { (source, _) ->
                source.priority + healthStore.get(source.id).reliabilityScore() / 10
            }
            .forEach { (_, parsed) ->
                parsed.channels.forEach { candidate ->
                    val keys = identityKeys(candidate)
                    val existingPrimary = keys.firstNotNullOfOrNull { aliasToPrimary[it] }

                    if (existingPrimary == null) {
                        val primary = keys.first()
                        merged[primary] = candidate
                        keys.forEach { aliasToPrimary[it] = primary }
                    } else {
                        val existing = merged[existingPrimary] ?: return@forEach
                        val alternates = (
                            existing.backupUris +
                                listOfNotNull(candidate.uri) +
                                candidate.backupUris
                            )
                            .filter { it != existing.uri }
                            .distinct()

                        merged[existingPrimary] = existing.copy(
                            logoUri = existing.logoUri ?: candidate.logoUri,
                            epgId = existing.epgId ?: candidate.epgId,
                            sourceNames = (
                                existing.sourceNames +
                                    candidate.sourceNames +
                                    candidate.sourceName
                                )
                                .filter(String::isNotBlank)
                                .distinct(),
                            backupUris = alternates
                        )
                        keys.forEach { aliasToPrimary[it] = existingPrimary }
                    }
                }
            }

        return merged.values
            .sortedWith(
                compareBy<Channel> { categoryRank(ChannelClassifier.category(it)) }
                    .thenBy { ChannelResolver.normalize(it.name) }
            )
            .mapIndexed { index, channel ->
                channel.copy(number = (1000 + index).toString())
            }
    }

    private fun identityKeys(channel: Channel): List<String> {
        val keys = linkedSetOf<String>()

        channel.canonicalId
            ?.trim()
            ?.lowercase()
            ?.takeIf(String::isNotBlank)
            ?.let { keys += "canonical:$it" }

        val normalizedName = ChannelResolver.normalize(channel.name)
        if (normalizedName.isNotBlank()) keys += "name:$normalizedName"

        channel.epgId
            ?.substringBefore('@')
            ?.trim()
            ?.lowercase()
            ?.takeIf(String::isNotBlank)
            ?.let { keys += "epg:$it" }

        if (keys.isEmpty()) keys += "uri:${channel.uri.orEmpty()}"
        return keys.toList()
    }

    private fun categoryRank(category: String): Int =
        ChannelClassifier.primaryCategories.indexOf(category).takeIf { it >= 0 } ?: 99

    private fun readEpg(channels: List<Channel>): EpgSchedule {
        if (channels.isEmpty()) return EpgSchedule()
        val current = linkedMapOf<String, ProgramInfo>()
        val timeline = linkedMapOf<String, MutableList<ProgramSlot>>()

        IptvSourceRegistry.epg
            .sortedByDescending(EpgSource::priority)
            .forEach { source ->
                val file = epgFile(source)
                if (file.isFile && file.length() > 0L) {
                    val parsed = XmlTvParser.parseSchedule(file, channels)
                    parsed.currentPrograms.forEach { (id, program) ->
                        current.putIfAbsent(id, program)
                    }
                    parsed.timeline.forEach { (id, programs) ->
                        timeline.getOrPut(id) { mutableListOf() }.addAll(programs)
                    }
                }
            }

        return EpgSchedule(
            currentPrograms = current,
            timeline = timeline.mapValues { (_, programs) ->
                programs
                    .distinctBy { "${it.startMillis}:${it.endMillis}:${it.title}" }
                    .sortedBy(ProgramSlot::startMillis)
                    .take(96)
            }
        )
    }

    private fun migrateLegacyCache() {
        val legacyPlaylist = File(legacyDirectory, "br.m3u")
        val primary = playlistFile(IptvSourceRegistry.builtIn.first())
        if (!primary.exists() && legacyPlaylist.isFile && legacyPlaylist.length() > 0L) {
            runCatching { legacyPlaylist.copyTo(primary, overwrite = false) }
        }

        val legacyEpg = File(legacyDirectory, "br-epg.xml")
        val firstEpg = epgFile(IptvSourceRegistry.epg.first())
        if (!firstEpg.exists() && legacyEpg.isFile && legacyEpg.length() > 0L) {
            runCatching { legacyEpg.copyTo(firstEpg, overwrite = false) }
        }
    }

    private fun playlistFile(source: IptvSource): File =
        File(directory, "playlist-${source.id}.m3u")

    private fun epgFile(source: EpgSource): File =
        File(directory, "epg-${source.id}.xml")

    private fun allCacheFiles(sources: List<IptvSource>): List<File> =
        sources.map(::playlistFile) + IptvSourceRegistry.epg.map(::epgFile)

    private fun isStale(file: File, ttlMillis: Long): Boolean =
        !file.isFile ||
            file.length() == 0L ||
            System.currentTimeMillis() - file.lastModified() > ttlMillis

    private fun isValidPlaylist(file: File): Boolean {
        if (!file.isFile || file.length() <= 0L) return false

        val first = runCatching {
            file.bufferedReader(Charsets.UTF_8).use { reader ->
                reader.readLine()?.removePrefix("\uFEFF")?.trim().orEmpty()
            }
        }.getOrDefault("")

        if (!first.startsWith("#EXTM3U", ignoreCase = true)) return false
        return parsePlaylist(
            IptvSource(
                id = "validator",
                name = "Validação",
                url = "https://localhost/",
                priority = 0,
                market = "validação"
            ),
            file
        ).channels.isNotEmpty()
    }

    private fun isValidEpg(file: File): Boolean {
        if (!file.isFile || file.length() <= 0L) return false
        val prefix = runCatching {
            file.inputStream().buffered().use { input ->
                val bytes = ByteArray(1024)
                val count = input.read(bytes)
                if (count <= 0) "" else String(bytes, 0, count, Charsets.UTF_8)
            }
        }.getOrDefault("")
        return prefix.contains("<tv", ignoreCase = true) || prefix.contains("<?xml", ignoreCase = true)
    }

    private fun download(
        url: String,
        target: File,
        maxBytes: Long,
        validator: ((File) -> Boolean)? = null
    ): Boolean {
        if (!url.startsWith("https://", ignoreCase = true)) return false
        val temp = File(target.parentFile, "${target.name}.tmp")
        var connection: HttpURLConnection? = null

        return runCatching {
            connection = (URL(url).openConnection() as HttpURLConnection).apply {
                instanceFollowRedirects = true
                connectTimeout = CONNECT_TIMEOUT_MS
                readTimeout = READ_TIMEOUT_MS
                requestMethod = "GET"
                setRequestProperty("User-Agent", USER_AGENT)
                setRequestProperty("Accept", "*/*")
                setRequestProperty("Accept-Encoding", "gzip")
            }

            val response = connection!!.responseCode
            require(response in 200..299) { "HTTP $response" }

            val raw = BufferedInputStream(connection!!.inputStream)
            val input: InputStream = if (
                connection!!.contentEncoding.equals("gzip", ignoreCase = true) ||
                url.endsWith(".gz", ignoreCase = true)
            ) {
                GZIPInputStream(raw)
            } else {
                raw
            }

            FileOutputStream(temp).use { output ->
                input.use { source ->
                    val buffer = ByteArray(DEFAULT_BUFFER_SIZE)
                    var total = 0L
                    while (true) {
                        val read = source.read(buffer)
                        if (read <= 0) break
                        total += read
                        require(total <= maxBytes) { "Resposta excedeu o limite seguro" }
                        output.write(buffer, 0, read)
                    }
                    output.fd.sync()
                }
            }

            require(temp.length() > 0L) { "Resposta vazia" }
            require(validator?.invoke(temp) != false) { "Conteúdo inválido" }

            if (!temp.renameTo(target)) {
                temp.copyTo(target, overwrite = true)
                temp.delete()
            }
            target.setLastModified(System.currentTimeMillis())
            true
        }.getOrElse {
            temp.delete()
            false
        }.also {
            connection?.disconnect()
        }
    }

    companion object {
        private const val USER_AGENT = "SANCHESTV/2.6 (Android TV)"
        private const val CONNECT_TIMEOUT_MS = 5_000
        private const val READ_TIMEOUT_MS = 22_000
        private const val PLAYLIST_TTL_MS = 3L * 60L * 60L * 1000L
        private const val EPG_TTL_MS = 3L * 60L * 60L * 1000L
        private const val MAX_PLAYLIST_BYTES = 64L * 1024L * 1024L
        private const val MAX_EPG_BYTES = 96L * 1024L * 1024L
    }
}

package com.mukasanches.zapptv.data

import android.content.Context
import org.json.JSONArray
import org.json.JSONObject

class PreferencesRepository(context: Context) {
    private val prefs = context.getSharedPreferences("zapptv", Context.MODE_PRIVATE)

    fun lastChannelId(): String? = prefs.getString(KEY_LAST_CHANNEL, null)

    fun setLastChannel(id: String) {
        prefs.edit().putString(KEY_LAST_CHANNEL, id).apply()
    }

    fun favorites(): Set<String> =
        prefs.getStringSet(KEY_FAVORITES, emptySet()).orEmpty().toSet()

    fun captionsEnabled(): Boolean = prefs.getBoolean(KEY_CAPTIONS_ENABLED, false)

    fun startInLastChannel(): Boolean = prefs.getBoolean(KEY_START_LAST_CHANNEL, false)

    fun preferredAudioLanguage(): String? =
        prefs.getString(KEY_AUDIO_LANGUAGE, "pt-BR")?.takeIf { it.isNotBlank() }

    fun setPreferredAudioLanguage(language: String?) {
        prefs.edit().putString(KEY_AUDIO_LANGUAGE, language.orEmpty()).apply()
    }

    fun maxVideoHeight(): Int = prefs.getInt(KEY_MAX_VIDEO_HEIGHT, 0)

    fun setMaxVideoHeight(height: Int) {
        prefs.edit().putInt(KEY_MAX_VIDEO_HEIGHT, height.coerceAtLeast(0)).apply()
    }

    fun setStartInLastChannel(enabled: Boolean) {
        prefs.edit().putBoolean(KEY_START_LAST_CHANNEL, enabled).apply()
    }

    fun setCaptionsEnabled(enabled: Boolean) {
        prefs.edit().putBoolean(KEY_CAPTIONS_ENABLED, enabled).apply()
    }

    fun setFavorite(id: String, favorite: Boolean) {
        val updated = favorites().toMutableSet()
        if (favorite) updated += id else updated -= id
        prefs.edit().putStringSet(KEY_FAVORITES, updated).apply()
    }

    fun recentChannelIds(limit: Int = 40): List<String> {
        val raw = prefs.getString(KEY_RECENT, null) ?: return emptyList()
        return runCatching {
            val array = JSONArray(raw)
            buildList {
                for (index in 0 until array.length()) {
                    val id = array.optString(index)
                    if (id.isNotBlank()) add(id)
                    if (size >= limit) break
                }
            }
        }.getOrDefault(emptyList())
    }

    fun watchCounts(): Map<String, Int> {
        val raw = prefs.getString(KEY_WATCH_COUNTS, null) ?: return emptyMap()
        return runCatching {
            val json = JSONObject(raw)
            buildMap {
                json.keys().forEach { key ->
                    val count = json.optInt(key, 0)
                    if (count > 0) put(key, count)
                }
            }
        }.getOrDefault(emptyMap())
    }

    fun recordTune(id: String) {
        val recent = recentChannelIds(limit = MAX_RECENTS)
            .filterNot { it == id }
            .toMutableList()
            .apply { add(0, id) }
            .take(MAX_RECENTS)

        val recentJson = JSONArray()
        recent.forEach(recentJson::put)

        val counts = watchCounts().toMutableMap()
        counts[id] = (counts[id] ?: 0).coerceAtMost(MAX_WATCH_COUNT - 1) + 1

        val countsJson = JSONObject()
        counts.forEach { (channelId, count) -> countsJson.put(channelId, count) }

        prefs.edit()
            .putString(KEY_RECENT, recentJson.toString())
            .putString(KEY_WATCH_COUNTS, countsJson.toString())
            .apply()
    }

    companion object {
        private const val KEY_LAST_CHANNEL = "last_channel"
        private const val KEY_FAVORITES = "favorites"
        private const val KEY_CAPTIONS_ENABLED = "captions_enabled"
        private const val KEY_START_LAST_CHANNEL = "start_last_channel"
        private const val KEY_AUDIO_LANGUAGE = "preferred_audio_language"
        private const val KEY_MAX_VIDEO_HEIGHT = "max_video_height"
        private const val KEY_RECENT = "recent_channels_v2"
        private const val KEY_WATCH_COUNTS = "watch_counts_v2"
        private const val MAX_RECENTS = 80
        private const val MAX_WATCH_COUNT = 1_000_000
    }
}

package com.mukasanches.zapptv.core

import android.content.Context
import android.os.SystemClock
import android.view.KeyEvent
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableIntStateOf
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import com.mukasanches.zapptv.data.ChannelRepository
import com.mukasanches.zapptv.data.DefaultChannelCatalog
import com.mukasanches.zapptv.data.IptvRepository
import com.mukasanches.zapptv.data.IptvSnapshot
import com.mukasanches.zapptv.data.PreferencesRepository
import com.mukasanches.zapptv.data.SourceHealth
import com.mukasanches.zapptv.data.IptvSource
import com.mukasanches.zapptv.model.Channel
import com.mukasanches.zapptv.model.ProgramInfo
import com.mukasanches.zapptv.model.ProgramSlot
import com.mukasanches.zapptv.playback.PlaybackTelemetry
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.delay
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

enum class AppScreen {
    HOME,
    WATCH,
    LIVE,
    MOVIES,
    SERIES,
    SPORTS,
    GUIDE,
    FAVORITES,
    SEARCH,
    SOURCES,
    DIAGNOSTICS
}

data class AppUiState(
    val loading: Boolean = false,
    val channels: List<Channel> = emptyList(),
    val programs: Map<String, ProgramInfo> = emptyMap(),
    val schedule: Map<String, List<ProgramSlot>> = emptyMap(),
    val favorites: Set<String> = emptySet(),
    val recentChannelIds: List<String> = emptyList(),
    val mostWatchedIds: List<String> = emptyList(),
    val selectedIndex: Int = 0,
    val screen: AppScreen = AppScreen.HOME,
    val iptvChannelCount: Int = 0,
    val epgProgramCount: Int = 0,
    val sourceCount: Int = 0,
    val healthySourceCount: Int = 0,
    val userSourceCount: Int = 0,
    val sourceHealth: Map<String, SourceHealth> = emptyMap(),
    val playbackStatus: String = "Aguardando reprodução",
    val playbackResolution: String = "—",
    val activeStreamIndex: Int = 0,
    val activeStreamCount: Int = 0,
    val activeStreamScore: Int = 0,
    val firstFrameMs: Long = 0L,
    val bufferCount: Int = 0,
    val bitrateKbps: Int = 0,
    val frameRate: Float = 0f,
    val videoCodec: String = "—",
    val lastOnlineRefreshMillis: Long = 0L,
    val onlineStatus: String = "Inicializando central IPTV",
    val message: String? = null
) {
    val currentChannel: Channel?
        get() = channels.getOrNull(selectedIndex)

    val currentProgram: ProgramInfo?
        get() = currentChannel?.let { programs[it.id] }
}

class ZappController(context: Context) {
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Main.immediate)
    private val prefs = PreferencesRepository(context)
    private val channelRepository = ChannelRepository()
    private val iptvRepository = IptvRepository(context)

    private val immediateChannels = DefaultChannelCatalog.channels
    private var pendingRestoreId: String? = prefs.lastChannelId()
    private var started = false
    private var refreshJob: Job? = null
    private var numericJob: Job? = null
    private var messageJob: Job? = null
    private var numericBuffer = ""
    private var previousChannelId: String? = null
    private var lastZapAt = 0L

    var state by mutableStateOf(
        AppUiState(
            channels = immediateChannels,
            favorites = prefs.favorites(),
            recentChannelIds = prefs.recentChannelIds(),
            mostWatchedIds = mostWatchedIds(),
            selectedIndex = immediateChannels.indexOfFirst { it.id == pendingRestoreId }
                .takeIf { it >= 0 } ?: 0
        )
    )
        private set

    var overlayGeneration by mutableIntStateOf(0)
        private set

    var overlayVisible by mutableStateOf(true)
        private set

    var quickGuideVisible by mutableStateOf(false)
        private set

    var captionsEnabled by mutableStateOf(prefs.captionsEnabled())
        private set

    var startInLastChannel by mutableStateOf(prefs.startInLastChannel())
        private set

    var preferredAudioLanguage by mutableStateOf(prefs.preferredAudioLanguage())
        private set

    var maxVideoHeight by mutableIntStateOf(prefs.maxVideoHeight())
        private set

    var playbackPanelVisible by mutableStateOf(false)
        private set

    var navigatorCategory by mutableStateOf("Todos")
    var navigatorFocusId by mutableStateOf<String?>(null)

    fun start() {
        if (started) return
        started = true

        scope.launch {
            val cached = withContext(Dispatchers.IO) { iptvRepository.loadCached() }
            applySnapshot(cached)
            if (startInLastChannel && state.currentChannel != null) {
                state = state.copy(screen = AppScreen.WATCH)
                showOverlay()
            }
            refreshOnline(force = false)

            while (isActive) {
                delay(EPG_REEVALUATION_MS)
                refreshOnline(force = false)
            }
        }
    }

    fun close() {
        scope.cancel()
    }

    fun handleKey(event: KeyEvent): Boolean {
        if (event.action != KeyEvent.ACTION_DOWN) return false

        if (event.keyCode == KeyEvent.KEYCODE_PROG_RED && event.repeatCount == 0) {
            refreshOnline(force = true, announce = true)
            return true
        }

        if (event.keyCode == KeyEvent.KEYCODE_SEARCH && event.repeatCount == 0) {
            quickGuideVisible = false
            open(AppScreen.SEARCH)
            return true
        }

        if (event.keyCode == KeyEvent.KEYCODE_BOOKMARK && event.repeatCount == 0) {
            quickGuideVisible = false
            open(AppScreen.FAVORITES)
            return true
        }

        if (state.screen != AppScreen.WATCH) return false

        if (
            event.repeatCount == 0 &&
            (event.keyCode == KeyEvent.KEYCODE_SETTINGS ||
                event.keyCode == KeyEvent.KEYCODE_MEDIA_AUDIO_TRACK)
        ) {
            playbackPanelVisible = !playbackPanelVisible
            if (playbackPanelVisible) {
                quickGuideVisible = false
                overlayVisible = false
            } else {
                showOverlay()
            }
            return true
        }

        if (event.keyCode == KeyEvent.KEYCODE_CAPTIONS && event.repeatCount == 0) {
            captionsEnabled = !captionsEnabled
            prefs.setCaptionsEnabled(captionsEnabled)
            showMessage(
                if (captionsEnabled) "Legendas ativadas" else "Legendas desativadas",
                1800
            )
            return true
        }

        if (playbackPanelVisible) {
            if (event.keyCode == KeyEvent.KEYCODE_BACK && event.repeatCount == 0) {
                playbackPanelVisible = false
                showOverlay()
                return true
            }
            return false
        }

        if (quickGuideVisible) {
            if (event.keyCode == KeyEvent.KEYCODE_BACK && event.repeatCount == 0) {
                quickGuideVisible = false
                showOverlay()
                return true
            }
            return false
        }

        val digit = digitForKey(event.keyCode)
        if (digit != null) {
            if (event.repeatCount == 0) enterChannelDigit(digit)
            return true
        }

        val zapDelta = when (event.keyCode) {
            KeyEvent.KEYCODE_CHANNEL_UP,
            KeyEvent.KEYCODE_PAGE_UP,
            KeyEvent.KEYCODE_MEDIA_NEXT,
            KeyEvent.KEYCODE_DPAD_RIGHT -> 1

            KeyEvent.KEYCODE_CHANNEL_DOWN,
            KeyEvent.KEYCODE_PAGE_DOWN,
            KeyEvent.KEYCODE_MEDIA_PREVIOUS,
            KeyEvent.KEYCODE_DPAD_LEFT -> -1

            else -> 0
        }

        if (zapDelta != 0) {
            val now = SystemClock.elapsedRealtime()
            if (event.repeatCount == 0 || now - lastZapAt >= ZAP_REPEAT_THROTTLE_MS) {
                lastZapAt = now
                zap(zapDelta)
            }
            return true
        }

        if (event.repeatCount > 0) return true

        return when (event.keyCode) {
            KeyEvent.KEYCODE_LAST_CHANNEL -> {
                lastChannel()
                true
            }
            KeyEvent.KEYCODE_GUIDE,
            KeyEvent.KEYCODE_DPAD_UP -> {
                open(AppScreen.GUIDE)
                true
            }
            KeyEvent.KEYCODE_DPAD_DOWN,
            KeyEvent.KEYCODE_MENU,
            KeyEvent.KEYCODE_DPAD_CENTER,
            KeyEvent.KEYCODE_ENTER -> {
                quickGuideVisible = true
                overlayVisible = false
                true
            }
            KeyEvent.KEYCODE_INFO -> {
                showOverlay()
                true
            }
            KeyEvent.KEYCODE_BACK -> {
                open(AppScreen.HOME)
                true
            }
            else -> false
        }
    }

    fun zap(delta: Int) {
        val channels = state.channels
        if (channels.isEmpty()) return
        val size = channels.size
        selectIndex((state.selectedIndex + delta).floorMod(size))
    }

    fun select(channel: Channel) {
        val index = state.channels.indexOfFirst { it.id == channel.id }
        if (index >= 0) selectIndex(index)
    }

    fun selectFromQuickGuide(channel: Channel) {
        quickGuideVisible = false
        select(channel)
    }

    fun closeQuickGuide() {
        quickGuideVisible = false
        showOverlay()
    }

    fun lastChannel() {
        val id = previousChannelId ?: return
        val index = state.channels.indexOfFirst { it.id == id }
        if (index >= 0) selectIndex(index)
    }

    fun toggleFavorite(channel: Channel) {
        val isFavorite = channel.id in state.favorites
        prefs.setFavorite(channel.id, !isFavorite)
        state = state.copy(favorites = prefs.favorites())
    }

    fun open(screen: AppScreen) {
        quickGuideVisible = false
        state = state.copy(screen = screen)
        if (screen == AppScreen.WATCH) showOverlay()
    }

    fun rememberNavigator(category: String, focusId: String?) {
        navigatorCategory = category
        navigatorFocusId = focusId
    }

    fun configuredSources(): List<IptvSource> = iptvRepository.configuredSources()

    fun setAudioMode(language: String?) {
        preferredAudioLanguage = language
        prefs.setPreferredAudioLanguage(language)
        showMessage(
            if (language.isNullOrBlank()) "Áudio: original/automático" else "Áudio: Português",
            1800
        )
    }

    fun setVideoHeight(height: Int) {
        maxVideoHeight = height.coerceAtLeast(0)
        prefs.setMaxVideoHeight(maxVideoHeight)
        showMessage(
            if (maxVideoHeight == 0) "Qualidade: automática" else "Qualidade: até ${maxVideoHeight}p",
            1800
        )
    }

    fun closePlaybackPanel() {
        playbackPanelVisible = false
        showOverlay()
    }

    fun toggleStartInLastChannel() {
        startInLastChannel = !startInLastChannel
        prefs.setStartInLastChannel(startInLastChannel)
        showMessage(
            if (startInLastChannel) "Inicialização: último canal" else "Inicialização: Início",
            2200
        )
    }

    fun addUserSource(url: String): Boolean {
        val added = iptvRepository.addUserSource(url) ?: return false
        showMessage("Fonte adicionada: " + added.name, 2600)
        refreshOnline(force = true)
        return true
    }

    fun removeUserSource(id: String) {
        iptvRepository.removeUserSource(id)
        showMessage("Fonte removida", 2200)
        refreshOnline(force = true)
    }

    fun updatePlaybackTelemetry(telemetry: PlaybackTelemetry) {
        state = state.copy(
            playbackStatus = telemetry.status,
            playbackResolution = telemetry.resolution,
            activeStreamIndex = telemetry.streamIndex,
            activeStreamCount = telemetry.streamCount,
            activeStreamScore = telemetry.score,
            firstFrameMs = telemetry.firstFrameMs,
            bufferCount = telemetry.bufferCount,
            bitrateKbps = telemetry.bitrateKbps,
            frameRate = telemetry.frameRate,
            videoCodec = telemetry.videoCodec
        )
    }

    fun showOverlay() {
        overlayVisible = true
        overlayGeneration += 1
        val generation = overlayGeneration
        scope.launch {
            delay(OVERLAY_TIMEOUT_MS)
            if (
                overlayGeneration == generation &&
                state.screen == AppScreen.WATCH &&
                !quickGuideVisible
            ) {
                overlayVisible = false
            }
        }
    }

    fun refreshOnline(force: Boolean, announce: Boolean = false) {
        if (refreshJob?.isActive == true) return
        if (announce) showMessage("Atualizando central IPTV…", 2500)

        refreshJob = scope.launch {
            val refreshed = withContext(Dispatchers.IO) { iptvRepository.refresh(force) }
            applySnapshot(refreshed)
            if (announce) showMessage(refreshed.status, 3500)
        }
    }

    private fun applySnapshot(snapshot: IptvSnapshot) {
        val loaded = channelRepository.load(snapshot.channels, snapshot.programs)
        val currentId = state.currentChannel?.id

        val restoreIndex = pendingRestoreId
            ?.let { wanted -> loaded.channels.indexOfFirst { it.id == wanted } }
            ?.takeIf { it >= 0 }

        val currentIndex = currentId
            ?.let { wanted -> loaded.channels.indexOfFirst { it.id == wanted } }
            ?.takeIf { it >= 0 }

        val selected = restoreIndex ?: currentIndex ?: 0
        if (restoreIndex != null) pendingRestoreId = null

        state = state.copy(
            loading = false,
            channels = loaded.channels,
            programs = loaded.programs,
            schedule = snapshot.schedule,
            favorites = prefs.favorites(),
            recentChannelIds = prefs.recentChannelIds(),
            mostWatchedIds = mostWatchedIds(),
            selectedIndex = selected.coerceIn(0, (loaded.channels.size - 1).coerceAtLeast(0)),
            iptvChannelCount = loaded.iptvChannelCount,
            epgProgramCount = snapshot.programs.size,
            sourceCount = snapshot.sourceCount,
            healthySourceCount = snapshot.healthySourceCount,
            userSourceCount = snapshot.userSourceCount,
            sourceHealth = snapshot.sourceHealth,
            lastOnlineRefreshMillis = snapshot.lastUpdatedMillis,
            onlineStatus = snapshot.status
        )
    }

    private fun enterChannelDigit(digit: Int) {
        numericBuffer = (numericBuffer + digit.toString()).takeLast(5)
        showMessage("Canal $numericBuffer", NUMERIC_COMMIT_DELAY_MS + 900)
        numericJob?.cancel()
        numericJob = scope.launch {
            delay(NUMERIC_COMMIT_DELAY_MS)
            commitNumericChannel()
        }
    }

    private fun commitNumericChannel() {
        val typed = numericBuffer
        numericBuffer = ""
        if (typed.isBlank()) return

        val exact = state.channels.indexOfFirst { it.number.trim() == typed }
        if (exact >= 0) {
            selectIndex(exact)
        } else {
            showMessage("Canal $typed não encontrado", 1800)
        }
    }

    private fun showMessage(text: String, durationMs: Long) {
        messageJob?.cancel()
        state = state.copy(message = text)
        showOverlay()
        messageJob = scope.launch {
            delay(durationMs)
            if (state.message == text) state = state.copy(message = null)
        }
    }

    private fun selectIndex(index: Int) {
        val old = state.currentChannel
        val next = state.channels.getOrNull(index) ?: return
        if (old?.id != next.id) previousChannelId = old?.id

        prefs.setLastChannel(next.id)
        if (old?.id != next.id) prefs.recordTune(next.id)

        state = state.copy(
            selectedIndex = index,
            screen = AppScreen.WATCH,
            message = null,
            recentChannelIds = prefs.recentChannelIds(),
            mostWatchedIds = mostWatchedIds()
        )
        showOverlay()
    }

    private fun mostWatchedIds(): List<String> =
        prefs.watchCounts()
            .entries
            .sortedByDescending { it.value }
            .take(50)
            .map { it.key }

    private fun digitForKey(keyCode: Int): Int? = when (keyCode) {
        in KeyEvent.KEYCODE_0..KeyEvent.KEYCODE_9 -> keyCode - KeyEvent.KEYCODE_0
        in KeyEvent.KEYCODE_NUMPAD_0..KeyEvent.KEYCODE_NUMPAD_9 ->
            keyCode - KeyEvent.KEYCODE_NUMPAD_0
        else -> null
    }

    private fun Int.floorMod(size: Int): Int {
        val value = this % size
        return if (value < 0) value + size else value
    }

    companion object {
        private const val ZAP_REPEAT_THROTTLE_MS = 150L
        private const val NUMERIC_COMMIT_DELAY_MS = 1100L
